import React, { useState, useCallback, useMemo } from 'react';
import { useObserver } from 'mobx-react';
import { observer } from 'mobx-react-lite';
import { CreateObjectModel } from './CreateObjectModel';

const CreateObjectView = ({ model }) => {
  const [assetId, setAssetId] = useState();

  const handleSelectAsset = useCallback(id => {
    setAssetId(id);
  }, []);

  const createObject = useCallback(() => {
    model.createObject(assetId).then(() => {
      // Do something after creating object
    });
    model.setSelectedAsset(null);
    setAssetId(undefined);
  }, [model, assetId]);

  const cleanupScene = useCallback(() => {
    model.cleanupScene().then(() => {
      // Do something after cleaning up scene
    });
  }, [model]);

  const availableAssets = useMemo(() => Array.from(model.availableAssets.values()), [model.availableAssets]);

  return useObserver(() => (
    <div id="create-object-view">
      <label htmlFor="asset-selector">Asset:</label>
      <select id="asset-selector" value={assetId} onChange={e => setAssetId(e.target.value)}>
        <option value="" />
        {availableAssets.map(asset => (
          <option key={asset.id} value={asset.id}>{asset.name}</option>
        ))}
      </select>
      <button onClick={createObject}>Create Object</button>
      <button onClick={cleanupScene}>Cleanup Scene</button>
    </div>
  ))
}

export default observer(CreateObjectView);
```

