```javascript
function sendSlackMessage(text, channel) {
  const webhookUrl = "https://hooks.slack.com/services/T0123456789/B0123456789/XXXXXXXXXXX"; // replace with your actual Webhook URL

  const payload = {
    text: text,
    channel: channel,
  };

  fetch(webhookUrl, {
    method: "POST",
    body: JSON.stringify(payload),
    headers: {
      "Content-type": "application/json; charset=UTF-8",
    },
  })
    .then((response) => response.json())
    .then((data) => console.log("Slack message sent successfully:", data))
    .catch((error) => console.error("Error sending Slack message:", error));
}
