Here's my implementation in Swift to correct the homophones in the given passage:

```swift
let inputPassage = """
Their is know weigh too no if yew see something and it seems too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't know the right weigh two do it. Weather or not yew know the difference between there, their, and they're, yew can't deny that its a common mistake. But can yew correct it programmatically using Swift?
"""

enum HomophoneType: String {
    case their = "there"
    case weigh = "way"
    case knot = "not"
    case right = "ight"
    case see = "see"
    case bee = "be"
    case too = "to"
}

struct Correction {
    let type: HomophoneType
    let replacement: String
}

let corrections: [Correction] = [
    Correction(type: .their, replacement: "there"),
    Correction(type: .weigh, replacement: "way"),
    Correction(type: .knot, replacement: "not"),
    Correction(type: .right, replacement: "ight"),
    Correction(type: .see, replacement: "see"),
    Correction(type: .bee, replacement: "be"),
    Correction(type: .too, replacement: "to"),
]

func replaceHomophones(_ text: String) -> String {
    var result = ""
    for (index, word) in text.components(separatedBy: .whitespaces).enumerated() {
        let homophonesToReplace = corrections.filter { $0.matches(word) }
        if !homophonesToReplace.isEmpty {
            let newWord = homophonesToReplace.reduce(word) { "\($1.replacement)\($0)" }
            result += newWord
        } else {
            result += word
        }
        if index != text.numberOfComponents(separatedBy: .whitespaces) - 1 {
            result += " "
        }
    }

