const myObject = {
  a: { b: 1, c: [2, { d: "e" }] },
  x: { y: "z", z: ["a", "b"] }
};

console.log(getMatches(myObject, 'a.c.d')); // Output: ["e"]
console.log(getMatches(myObject, 'x.y')); // Output: ["z"]
console.log(getMatches(myObject, 'x.z.0')); // Output: ["a"]
console.log(getMatches(myObject, 'x.z.1')); // Output: ["b"]
console.log(getMatches(myObject, 'b')); // Output: [] (no match found)

