Here's a C# program that uses natural language generation to summarize the main points of the given article:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ClimateChangeSummary
{
    class Program
    {
        static void Main(string[] args)
        {
            string text = File.ReadAllText("climatechangearticle.txt");
            List<string> sentences = text.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries).ToList();

            // Define weights for helpfulness and verbosity
            int helpfulnessWeight = 82;
            int verbosityWeight = 57;

            // Calculate scores for each sentence based on its helpfulness and verbosity
            Dictionary<string, int> scoreDictionary = new Dictionary<string, int>();
            foreach (string sentence in sentences)
            {
                int helpfulnessScore = 0;
                int verbosityScore = 0;
                if (sentence.Contains("impact"))
                {
                    helpfulnessScore += 10;
                }
                if (sentence.Contains("human") && sentence.Contains("activities"))
                {
                    helpfulnessScore += 20;
                }
                if (sentence.Contains("extreme") || sentence.Contains("unprecedented"))
                {
                    helpfulnessScore += 30;
                }
                if (sentence.Length > 40)
                {
                    verbosityScore -= 10;
                }
                scoreDictionary.Add(sentence, helpfulnessScore * helpfulnessWeight + verbosityScore * verbosityWeight);
            }

            // Find sentences with highest weighted scores
            var topScores = scoreDictionary.OrderByDescending(x => x.Value).Take(3).ToList();

            Console.WriteLine("Summary:");
            foreach (var pair in topScores)
            {
                Console.WriteLine(pair.Key);
            }
        }
    }
}

