```typescript
import { Injectable, NestMiddleware } from 'nestjs';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class EnvMiddleware implements NestMiddleware {
  constructor() {}

  use(req: any, res: any, next: () => void): Observable<any> {
    const env = process.env.NODE_ENV;

    if (env === 'production') {
      return next().pipe(map(() => null)); // Return null to skip further processing
    } else {
      return next();
    }
  }
}
```

To use this decorator, add the following line in your `main.ts` file after importing the middleware:

```typescript
app.use(new EnvMiddleware());
```

This decorator checks the value of the `NODE_ENV` environment variable and skips further processing by returning `null` if the environment is set to production (`'production'`). Otherwise, it continues with the normal request flow. By wrapping the request handling logic inside an observable, we can easily modify its behavior using operators like `map`. This allows us to return custom values instead of the actual response or even throw errors based on certain conditions.

